const svCta=()=>`<article class="card" style="background:var(--rosso);border:0;color:#fff"><div class="tx" style="justify-content:center;min-height:260px;gap:16px"><h3 style="font-size:26px">Non sai da dove partire?</h3><p style="color:#fff">Raccontaci l'obiettivo: ti aiutiamo a trovare il primo passo.</p><a class="btn" href="#contatti" style="background:#fff;color:var(--rosso-h);align-self:flex-start">Richiedi una consulenza</a></div></article>`;
const svCard=k=>{const s=SV[k];return `<article class="card"><div class="cv">${cv(s.s,s.o)}</div><div class="tx"><h3>${s.nav}</h3><p>${SVV[k]}</p>${L(k,'Scopri','arr')}</div></article>`};
const svPage=k=>{const s=SV[k];const e=s.extra;
return hero({crumb:[['Servizi','servizi'],[s.nav]],lab:s.lab,h1:s.h1,lead:s.lead,ctas:CTAB+L('servizi','Tutti i servizi','btn btn-o'),s:s.s,o:s.o})+
`<section class="sec tight"><div class="in">${sh('Cosa risolviamo','Problemi che {conosciamo bene}')}<div class="cards c4">${s.pr.map((p,i)=>`<div class="box"><span class="ico">0${i+1}</span><p style="color:var(--ink);font-weight:500">${p}</p></div>`).join('')}</div></div></section>`+
`<section class="sec alt"><div class="in split"><div class="tx"><p class="lab">Cosa facciamo</p><h2 class="h2">Le attività, {passo dopo passo}</h2>${chk(s.does)}${s.todoDo?`<p>${TODO(s.todoDo)}</p>`:''}</div>${vis(s.s,s.o)}</div></section>`+
(e?`<section class="sec"><div class="in split rev">${vis(e.s,e.o)}<div class="tx"><p class="lab">Approfondimento</p><h2 class="h2">${R(e.h)}</h2><p class="lead">${e.p}</p>${e.list?chk(e.list):''}</div></div></section>`:'')+
`<section class="sec${e?' alt':''}"><div class="in">${sh('Tecnologie','Gli strumenti che {usiamo}')}${chips(s.tech)}${s.techNote?`<p style="margin-top:16px;color:var(--grigio)">${s.techNote}</p>`:''}</div></section>`+
`<section class="sec${e?'':' alt'}"><div class="in">${sh('Cosa cambia per te','I benefici {concreti}')}<div class="cards c4">${s.gain.map(g=>`<div class="box red"><p style="color:var(--ink);font-weight:600">${g}</p></div>`).join('')}</div></div></section>`+
`<section class="sec tight" style="padding-top:clamp(24px,3cqi,40px)"><div class="in"><p class="meta" style="margin-bottom:12px">Continua con</p><div class="chips">${s.links.map(l=>L(l,(PG[l]||{}).t||l)).join('')}</div></div></section>`+
CTA(s.q,'Raccontaci la tua esigenza: ti ricontattiamo per capire insieme da dove partire.','Richiedi una consulenza','contatti',s.s,s.o,s.b2)};

